// 一组用户数据（模拟从后端接口拿到的 JSON）
const users = [
  { name: '小明', age: 17, role: 'student' },
  { name: '小红', age: 25, role: 'admin' },
  { name: '小刚', age: 31, role: 'user' },
  { name: '小丽', age: 19, role: 'student' }
];

// 1. filter：筛选出成年用户（age >= 18），返回新数组，不改动 users
const adults = users.filter((user) => user.age >= 18);
console.log('成年用户:', adults.map((u) => u.name));
// 输出: 成年用户: [ '小红', '小刚', '小丽' ]

// 2. map：把每个用户对象转换成 "名字(年龄)" 字符串
const labels = adults.map((user) => `${user.name}(${user.age})`);
console.log('标签:', labels);
// 输出: 标签: [ '小红(25)', '小刚(31)', '小丽(19)' ]

// 3. reduce：汇总所有成年用户的总年龄（注意第二个参数 0 是初始值）
const totalAge = adults.reduce((sum, user) => sum + user.age, 0);
console.log('总年龄:', totalAge);
// 输出: 总年龄: 75

// 4. 链式调用：一行完成「过滤 + 转换」，数据流水线一目了然
const studentNames = users
  .filter((user) => user.role === 'student')
  .map((user) => user.name);
console.log('学生:', studentNames);
// 输出: 学生: [ '小明', '小丽' ]

// 5. 用 reduce 把数组转成对象：{ 小明: 17, 小红: 25, ... }
const ageMap = users.reduce((acc, user) => {
  acc[user.name] = user.age;   // 往累加器对象上添加属性
  return acc;                  // 必须返回新的累加器
}, {});
console.log('年龄表:', ageMap);
// 输出: 年龄表: { 小明: 17, 小红: 25, 小刚: 31, 小丽: 19 }

// 验证原数组没有被修改（filter/map/reduce 都是非破坏性的）
console.log('原数组长度仍是:', users.length); // 输出: 4

